import { createHmac } from 'node:crypto';

/**
 * Main-process authorizing-gesture signing (Phase 2 final integration).
 *
 * The gesture key is a fresh per-launch secret generated by Electron main,
 * delivered to the trusted backend child inside the private stdin bootstrap
 * (domain-separated from the channel HMAC key), and held only in main-process
 * memory. The renderer never sees it and cannot ask for arbitrary signatures:
 * the only signing entry point is {@link signAuthorizingGesture}, which main
 * invokes exclusively after a genuine affirmative native confirmation.
 *
 * Byte-level contract with the Python verifier
 * (`aether.core.planning.authorizing_gesture`): the signed payload is the
 * canonical JSON below — keys sorted, compact separators, `plan_hash`
 * lower-cased, and `asserted_at` rendered exactly like Python's
 * `datetime.isoformat()` for a UTC instant (no fractional part when the
 * millisecond component is zero, otherwise six fractional digits). The
 * golden vectors in `tests/gesture.test.ts` pin both sides to identical
 * bytes; any drift fails the build.
 */

export interface GestureBindingInput {
  taskId: string;
  planRevision: number;
  planHash: string;
  previewId: string;
  previewDigest: string;
  scopeDigest: string;
}

export interface SignedGesturePayload {
  nonce: string;
  binding: {
    task_id: string;
    plan_revision: number;
    plan_hash: string;
    preview_id: string;
    preview_digest: string;
    scope_digest: string;
  };
  asserted_at: string;
  user_intent: string;
  signature: string;
}

const SHA256_HEX = /^[0-9a-fA-F]{64}$/;
const UUID_SHAPE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
const NONCE_SHAPE = /^[0-9a-f]{64}$/;

function assertBinding(binding: GestureBindingInput): void {
  if (!UUID_SHAPE.test(binding.taskId) || !UUID_SHAPE.test(binding.previewId)) {
    throw new Error('gesture binding identity is malformed');
  }
  if (!Number.isSafeInteger(binding.planRevision) || binding.planRevision < 1) {
    throw new Error('gesture binding plan revision is malformed');
  }
  if (
    !SHA256_HEX.test(binding.planHash)
    || !SHA256_HEX.test(binding.previewDigest)
    || !SHA256_HEX.test(binding.scopeDigest)
  ) {
    throw new Error('gesture binding digest is malformed');
  }
}

/** Render a Date exactly like Python `datetime.isoformat()` (UTC). */
export function pythonIsoformatUtc(instant: Date): string {
  const iso = instant.toISOString(); // YYYY-MM-DDTHH:mm:ss.sssZ
  const base = iso.slice(0, 19);
  const millis = iso.slice(20, 23);
  if (millis === '000') return `${base}+00:00`;
  return `${base}.${millis}000+00:00`;
}

export function canonicalBindingJson(binding: GestureBindingInput): string {
  assertBinding(binding);
  const canonical = {
    plan_hash: binding.planHash.toLowerCase(),
    plan_revision: binding.planRevision,
    preview_digest: binding.previewDigest,
    preview_id: binding.previewId,
    scope_digest: binding.scopeDigest,
    task_id: binding.taskId,
  };
  return JSON.stringify(canonical);
}

export function canonicalGesturePayloadJson(
  nonce: string,
  binding: GestureBindingInput,
  assertedAt: Date,
  userIntent: string,
): string {
  if (!NONCE_SHAPE.test(nonce)) throw new Error('gesture nonce is malformed');
  const payload = {
    asserted_at: pythonIsoformatUtc(assertedAt),
    binding: JSON.parse(canonicalBindingJson(binding)) as Record<string, unknown>,
    nonce,
    user_intent: userIntent,
  };
  return JSON.stringify(payload);
}

/**
 * Sign one authorizing gesture. `userIntent` must be exactly `APPROVE`;
 * anything else is refused here so a stray caller can never mint a
 * non-approval (or ambiguous) signature.
 */
export function signAuthorizingGesture(
  key: Buffer,
  nonce: string,
  binding: GestureBindingInput,
  assertedAt: Date,
  userIntent: string,
): SignedGesturePayload {
  if (key.length < 32) throw new Error('gesture key is too short');
  if (userIntent !== 'APPROVE') throw new Error('only an explicit APPROVE gesture may be signed');
  const canonical = canonicalGesturePayloadJson(nonce, binding, assertedAt, userIntent);
  const signature = createHmac('sha256', key).update(canonical, 'utf8').digest('hex');
  return {
    nonce,
    binding: {
      task_id: binding.taskId,
      plan_revision: binding.planRevision,
      plan_hash: binding.planHash.toLowerCase(),
      preview_id: binding.previewId,
      preview_digest: binding.previewDigest,
      scope_digest: binding.scopeDigest,
    },
    asserted_at: pythonIsoformatUtc(assertedAt),
    user_intent: userIntent,
    signature,
  };
}
